    function parseRest(s){if(s.includes('2–3'))return 150;if(s.includes('2 min'))return 120;if(s.includes('60–90')||s.includes('90'))return 90;return 60}function showTime(){const m=String(Math.floor(timer/60)).padStart(2,'0'),s=String(timer%60).padStart(2,'0');$('#restTime').textContent=`${m}:${s}`}
